import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(8,1,{
 title:'世界模型的任务：给定现在和动作，预测接下来',summary:'用一个一维移动环境定义状态、观测和动作，明确什么叫动作条件动态预测。',prerequisites:['w1-l3','w6-l3'],
 terms:[T('状态 state','用于描述环境并支持预测的变量集合；是否足够取决于任务。','小车位置与速度可能比只有位置更能预测下一刻。'),T('观测 observation','传感器实际提供的信息，可能只能反映部分状态。','一帧图像可能无法确定物体正向左还是向右移动。'),T('动作 action','系统施加给环境的控制输入。','移动指令、关节目标或力，必须明确单位和执行时间。'),T('世界模型 world model','学习环境变化规律并用于预测的模型；本课关注动作条件动态模型。','输入历史与候选动作，预测下一状态或未来观测。'),T('动作条件 action conditioning','把动作作为预测未来的条件。','相同起点下向左与向右应产生不同且符合环境的未来。')],
 sections:[P('第 1 步：先定义一个能检查答案的世界','设一维位置 s，每次动作 a 代表移动量，真实规则是 s_next=s+a。这是人为定义的环境，目标是让模型从数据学到这条动态规律，而不是把规则直接藏在预测器里。','一条样本应包含 s、a、s_next，三者的时间关系必须明确。真实机器人还需考虑动作延迟、坐标系和单位；错一个时间步就可能变成错误监督。'),P('第 2 步：区分看到的与真正决定未来的','只有某一刻的位置，可能无法知道正在向左还是向右移动；需要速度或历史帧。观察不足时，同样观测可能对应多个未来，并不一定是模型不够大。','如果任务存在不确定性，预测分布或多个合理未来可能比一个平均未来更合适。先判断输入是否包含必要信息，再讨论结构与训练预算。'),P('第 3 步：检查模型是否真的使用动作','先固定起点，改变动作，看预测是否朝正确方向变化。还可以把动作打乱或替换成零，与正常动作输入对照。输入张量里存在 action 字段，不代表网络学会依赖它。','若数据中动作总是相似，忽略动作也可能得到很低误差。要设计有辨别力的验证集，例如同一起点施加不同动作，并比较对应真实结果。'),P('第 4 步：把视频生成和世界建模联系起来','逼真视频可以来自外观和时间规律学习，但用于机器人交互还需要对动作后果的正确预测。评价要同时看视觉、动态、动作响应和长期稳定性。','Decoder-only、AR、连续 latent 是不同维度：可以用因果主干按历史预测未来视觉表示，再用解码器恢复图像；是否构成可用世界模型仍要通过具体任务证明。')],
 worked:{title:'同一起点的三种动作',steps:['起点 s=2。动作 a=−1 时真实下一状态为 1。','动作 a=0 时为 2；动作 a=1 时为 3。','若模型不管动作都预测 2，只在中间这一项正确。','因此需要动作有变化的对照，不能只看静止场景。'],takeaway:'动作条件能力需要行为证据，不能从模型名字推断。'},
 example:{code:'state = 2.0\nfor action in [-1.0, 0.0, 1.0]:\n    truth = state + action\n    action_aware = state + 0.9*action\n    ignores_action = state\n    print(action, truth, action_aware, ignores_action)',output:'-1.0 1.0 1.1 2.0\n0.0 2.0 2.0 2.0\n1.0 3.0 2.9 2.0',explanation:'两种预测器在这里是人为设定的对照，实际训练在下载的 tiny_world_model.py 中完成。'},
 checks:[Q('一帧图片是否总能包含预测未来所需的全部信息？','想象位置相同、速度相反的两个场景。','不能。可能需要历史、速度或其他观测来区分隐藏状态。',1),Q('怎样验证预测器没有忽略动作？','固定其他条件，改变动作并比较真实后果。','设计同一起点不同动作、打乱动作等对照，并检查预测是否与真实环境响应一致。',2)],
 practice:{title:'先搭好动态数据的契约',steps:[A('写一条状态、动作、下一状态的样本，并标时间。','能明确动作作用于哪一段时间。','不要把 a_t 与错误的 s_next 配对。'),A('阅读 tiny_world_model.py 的真实环境和数据生成。','区分环境函数与可训练预测器。','不能把真实规则直接放进待评测模型而宣称学会。'),A('运行 CPU 小规模训练，并保存动作打乱对照指标。','看到单步、rollout、保持状态基线和动作打乱结果。','先按 README 原命令跑通，再改变实验变量。')]},links:[{label:'世界模型训练脚本',href:'./downloads/tiny_world_model.py'},{label:'运行说明',href:'./downloads/README.md'}],sources:[S.vjepa,S.policy]
}),
L(8,2,{
 title:'JEPA：预测表示，不必逐像素猜未来',summary:'用遮住一部分图像的例子解释 JEPA，再把它连接到视频和动作条件预测。',prerequisites:['w6-l2','w6-l3','w8-l1'],
 terms:[T('JEPA，Joint-Embedding Predictive Architecture','在表示空间中，从可见内容预测目标内容表示的一类预测架构。','预测被遮挡区域的表示，不一定直接预测该区域的 RGB 像素。'),T('上下文编码器与目标编码器','前者读取允许看到的部分，后者产生需要预测的目标表示。','目标编码器的输入可能包含上下文看不到的内容。'),T('stop-gradient 停止梯度','保留某个数值作为目标，但不让当前损失沿该分支反向更新。','学生向教师目标靠近，教师可能通过 EMA 等其他机制更新。'),T('表示塌缩 collapse','不同输入得到几乎相同表示，丢失区分能力的退化情况。','预测误差可能很小，但表示对任务没有用。')],
 sections:[P('第 1 步：像素预测并非唯一的学习问题','一片树叶未来的细小纹理很难精确预测，但“物体还在移动、接近桌边”可能对控制更重要。表示预测试图学习任务相关的抽象信息，减少必须逐像素还原的负担。','这是建模取舍，不是保证一定更好。若表示丢掉了精细接触位置，而任务恰好依赖它，抽象过头也会失败。'),P('第 2 步：搭出上下文、预测器与目标三部分','在图像 JEPA 的直觉例子中，上下文编码器看可见区域，预测器根据上下文与目标位置预测目标表示；目标编码器对目标内容产生监督。损失比较两份表示。','关键是可见性：上下文不能偷偷看到目标内容的同一表示。目标编码器怎样更新、哪些梯度停止、遮挡区域怎样采样，都属于方法定义，不能省略。'),P('第 3 步：理解防止无意义的一致','如果所有图像都被编码成同一个常向量，预测它很容易，但模型什么也没区分。JEPA 类方法需要通过目标分支设计、预测任务和训练机制等避免这种退化。','不同方法不一定使用相同的防塌缩配方。不能只写一行向量 MSE 就宣称实现了完整 JEPA，也不能把所有表示匹配都叫同一个方法。'),P('第 4 步：连接到视频与行动','视频预测可以把过去表示作为上下文，未来表示作为目标；动作条件版本再接入动作。模型没有像素解码器时，不能直接展示预测视频，但仍可在表示质量、下游预测或规划接口上评测。','若要生成图像，需要额外解码路径；若要执行动作，需要策略或规划器。表示预测能力不会自动提供这两个模块。')],
 worked:{title:'两份表示的误差不等于像素误差',steps:['目标表示 z=[1,0]，预测 z_hat=[0.8,0.1]。','平方差分别为 0.04 和 0.01，平均为 0.025。','这个分数只说明该表示空间中的接近程度。','是否保留位置、动作后果或视觉细节，要通过相应的额外任务验证。'],takeaway:'学习目标所在空间决定 loss 能直接告诉你什么。'},
 example:{code:'target = [1.0, 0.0]\nprediction = [0.8, 0.1]\nrepresentation_loss = sum((a-b)**2 for a,b in zip(target,prediction))/len(target)\nprint("representation MSE", round(representation_loss, 3))\nprint("pixel decoder supplied", False)',output:'representation MSE 0.025\npixel decoder supplied False',explanation:'向量是给定的，不包含编码器训练、防塌缩机制或真实 JEPA 模型。这里只看损失所处的空间。'},
 checks:[Q('没有像素解码器的 JEPA 能否直接输出预测视频？','从表示回到 RGB 的步骤在哪里？','不能直接输出，需要额外解码器；仍可以在表示和下游任务中评价它。',3),Q('把所有输入映射到同一向量，表示预测误差很小，是否意味着学到了好特征？','不同状态还能区分吗？','不意味着。这可能是塌缩，需要检查表示区分性与下游任务表现。',2)],
 practice:{title:'把 JEPA 画成可审查的训练图',steps:[A('画上下文编码器、预测器、目标编码器与损失。','每条输入路径和停止梯度位置都标明。','目标分支参与前向不意味着它被同一损失直接更新。'),A('列出表示应该保留与可以忽略的信息。','针对你的世界模型任务说明理由。','不能把“抽象”简单等同于“更高级”。'),A('设计一个表示塌缩检查和一个任务检查。','前者看不同样本是否可区分，后者看是否能完成所需预测。','只看目标 loss 不足以排除退化。')]},sources:[S.jepa,S.vjepa]
}),
L(8,3,{
 title:'rollout：一步预测正确，为什么走远了会漂移',summary:'在同一组动作上对比真实历史和预测历史，计算误差随预测长度的变化。',prerequisites:['w8-l1','w2-l3'],
 terms:[T('rollout 连续展开','把模型输出反复作为后续输入，预测一段未来。','第 2 步用第 1 步预测的状态，而不再偷用真实状态。'),T('horizon 预测长度','连续预测多远，常以时间步数表示。','报告 1、5、10、20 步误差可以看到漂移趋势。'),T('误差累积','前面预测的偏差影响后续输入，使后续误差继续变化。','系统性多加 0.1 的偏差可能逐步增大。'),T('保持状态基线 persistence','用当前状态作为未来预测的简单参照。','静止场景中可能很强，运动场景中会逐渐变差。')],
 sections:[P('第 1 步：为两种评价固定同一条真实轨迹','真实环境 s_next=s+a，初始 s=0，每步动作为 1，真实轨迹为 [0,1,2,3]。设模型每步预测时额外多加 0.1。先不要训练，单独观察偏差怎样传播。','使用真实历史时，三次预测分别从真实 0、1、2 出发，结果为 [1.1,2.1,3.1]。每一步误差都是 0.1。'),P('第 2 步：让模型真正使用自己的输出','自由运行从 0 预测 1.1，接着从 1.1 预测 2.2，再从 2.2 预测 3.3。误差变成 [0.1,0.2,0.3]，后面越来越偏。','这并不表示所有系统的误差都线性增长。真实动态可能放大、纠正或截断误差。关键是必须实际展开，而不能用单步成绩代替。'),P('第 3 步：逐步计算误差曲线','本例真实历史三步平均 MSE 为 0.01；自由运行平均为 (0.01+0.04+0.09)/3≈0.0467。还应报告最后一步误差，因为平均值可能隐藏远期失败。','多维状态要明确按维度和时间如何平均。动作单位、位置量纲不同可能影响数值占比，必要时分维度报告，不能只展示一个未定义的 loss 名字。'),P('第 4 步：避免评价过程偷偷校正模型','free-running 过程中若每几步重新输入真实状态，就成了另一种协议。重置频率必须报告，不能与完全自由展开混比。真实机器人闭环中重新观察环境是合理策略，但评测目的不同。','按完整轨迹划分数据。输入噪声、长跨度训练或其他稳定化方法是否有效，需要同时比较单步与长期表现，而不是只看训练曲线。')],
 worked:{title:'同一个偏差，两种历史来源',steps:['真实历史预测：[1.1,2.1,3.1]，误差 [0.1,0.1,0.1]。','自由运行预测：[1.1,2.2,3.3]，误差 [0.1,0.2,0.3]。','前者平均 MSE=0.01，后者约为 0.0467。','说明必须在目标使用方式下评测，而不能只看每步是否“差得不多”。'],takeaway:'输入来自真实数据还是来自模型，是评测协议的一部分。'},
 example:{code:'truth = [0.0, 1.0, 2.0, 3.0]\nfree = [0.0]\nfor _ in range(3):\n    free.append(free[-1]+1.0+0.1)\nerrors = [p-y for p,y in zip(free[1:],truth[1:])]\nprint("errors", [round(x, 2) for x in errors])\nprint("rollout MSE", round(sum(x*x for x in errors)/len(errors), 4))',output:'errors [0.1, 0.2, 0.3]\nrollout MSE 0.0467',explanation:'这里人为给定系统偏差，只用于观察机制。下载训练脚本会用真实训练得到的预测器计算同类指标。'},
 checks:[Q('单步误差低能否保证 30 步预测也好？','考虑模型自己的误差成为下一步输入。','不能，需要按预测长度测量自由展开误差，并与真实历史条件对比。',1),Q('每步都喂真实状态，还能称为完全自由运行吗？','模型有没有使用自己的上一步结果？','不能。那是使用真实历史的条件评测，必须与 free-running 分开报告。',3)],
 practice:{title:'完成一份世界模型基线报告',steps:[A('在交互实验里比较使用真实历史与自身预测。','记录相同增益和 horizon 下的差异。','不要一边切模式一边改其他参数。'),A('完成 rollout 误差代码练习。','正确处理多维状态、时间和目标长度。','先用完美预测器确认误差为零。'),A('跑 tiny_world_model.py，保留不同 horizon 误差、保持状态和打乱动作对照。','形成一份真正训练模型的结果，而不是把交互演示当成绩。','按 README 使用 --output 保存日志和配置。')]},links:[{label:'rollout 交互实验',href:'#/labs/rollout'},{label:'rollout 误差练习',href:'#/code/rollout-error'}],sources:[S.vjepa,S.policy]
})];
